const RELATION_STATES = new Set(['亲密', '友好', '普通', '疏远', '紧张', '敌对', '竞争', '复杂', '恋爱', '暧昧', '伴侣', '家人', '同事', '同学', '师生', '主从', '特殊']);
const SOURCE_TYPES = new Set(['character_card', 'user_persona', 'world_info']);
