        out += `<path class="pc-arch" d="M${x - 6} ${POSTCARD_SCENE_HORIZON - h} L${x} ${POSTCARD_SCENE_HORIZON - h - next(7, 12)} L${x + 6} ${POSTCARD_SCENE_HORIZON - h} Z"/>`;
