      <path class="pc-arch" d="M0 ${POSTCARD_SCENE_HORIZON + 5} Q${middle} ${next(40, 49)} ${POSTCARD_SCENE_WIDTH} ${POSTCARD_SCENE_HORIZON + 5} Z"/>
